#define nam tracksmith_t3k_nam
#include "Processor.h"
#undef nam
#include "../source/SessionFile.h"
#include "../source/NativeInstruments.h"
#include <iostream>
#include <cmath>
static void require(bool ok,const char* what){if(!ok){std::cerr<<"FAIL: "<<what<<'\n';std::exit(1);}}
static bool settled(TONE3000Processor& p){const auto end=juce::Time::getMillisecondCounter()+20000;while(juce::Time::getMillisecondCounter()<end){auto s=p.getChainState(-1);bool ready=true;for(const auto* a:{s["chain"].getArray(),s["chainRight"].getArray()})if(a)for(const auto& x:*a)if(x["kind"].toString()=="tone"&&!bool(x["loaded"]))ready=false;if(ready&&!p.isChainEditFadeHeld())return true;juce::Thread::sleep(20);}return false;}
int main(int argc,char** argv){juce::ScopedJuceInitialiser_GUI init;require(argc>1,"A2 fixture argument");
 auto original=createTracksmithTone3000();auto& p=static_cast<TONE3000Processor&>(*original);p.setRateAndBufferSizeDetails(48000,256);p.prepareToPlay(48000,256);
 auto probe=[&](const char* stage){juce::AudioBuffer<float> b(2,256);juce::MidiBuffer m;for(int c=0;c<2;++c)for(int n=0;n<256;++n)b.setSample(c,n,.03f);p.processBlock(b,m);for(int c=0;c<2;++c)for(int n=0;n<256;++n)require(std::isfinite(b.getSample(c,n)),stage);juce::Thread::sleep(200);};probe("empty");
 auto invalid=p.loadLocalTonePath(juce::File::getCurrentWorkingDirectory().getChildFile("missing.nam"));require(invalid["error"].toString().isNotEmpty(),"missing model reports error");
 auto loaded=p.loadLocalTonePath(juce::File(juce::String::fromUTF8(argv[1])));require(loaded["error"].isVoid()&&loaded["blockId"].toString().isNotEmpty(),"local A2 model accepted");require(settled(p),"A2 engine loaded");probe("A2 only");
 auto ir=juce::File::getSpecialLocation(juce::File::tempDirectory).getNonexistentChildFile("tracksmith-test-ir",".wav");{juce::WavAudioFormat wav;auto stream=ir.createOutputStream();std::unique_ptr<juce::AudioFormatWriter> writer(wav.createWriterFor(stream.release(),48000,1,24,{},0));require(bool(writer),"IR fixture writer");juce::AudioBuffer<float> b(1,256);b.clear();b.setSample(0,0,.5f);require(writer->writeFromAudioSampleBuffer(b,0,256),"IR fixture saved");}
 auto cab=p.loadLocalTonePath(ir);require(cab["error"].isVoid(),"local cabinet IR accepted");require(settled(p),"IR engine loaded");
 juce::AudioBuffer<float> b(2,256);juce::MidiBuffer midi;double energy=0;for(int block=0;block<80;++block){for(int c=0;c<2;++c)for(int n=0;n<256;++n)b.setSample(c,n,.05f*std::sin(float(block*256+n)*.06f));p.processBlock(b,midi);for(int c=0;c<2;++c)for(int n=0;n<256;++n){auto x=b.getSample(c,n);if(!std::isfinite(x)){std::cerr<<"nonfinite block="<<block<<" channel="<<c<<" sample="<<n<<" chain="<<juce::JSON::toString(p.getChainState(-1)).toStdString()<<"\n";}require(std::isfinite(x),"finite A2 and IR output");energy+=x*x;}}require(energy>1e-9,"audible model output");
 juce::Thread::sleep(200);auto* parameter=p.parameters.getParameter("inputLevel");require(parameter!=nullptr,"input parameter exposed");parameter->setValueNotifyingHost(.61f);juce::MemoryBlock state;p.getStateInformation(state);require(state.getSize()>100,"state serialized");
 SavedSession project;project.tracks.push_back({"Guitar"});auto* insert=new juce::DynamicObject;insert->setProperty("channel",0);insert->setProperty("slot",0);insert->setProperty("description",NativeInstruments::tone3000Description().createXml()->toString());insert->setProperty("state",state.toBase64Encoding());insert->setProperty("bypass",false);project.inserts.add(insert);auto sessionFile=ir.getSiblingFile("Tone3000-recall.tracksmith");SavedSession decoded;require(SessionFile::decode(SessionFile::encode(project,sessionFile),sessionFile,decoded).wasOk(),"Tracksmith session round trip");juce::MemoryBlock savedState;require(savedState.fromBase64Encoding(decoded.inserts[0]["state"].toString()),"saved insert state decoded");require(decoded.inserts[0]["description"].toString().contains("tracksmith-native-tone3000"),"native session identity");
 auto copy=createTracksmithTone3000();auto& restored=static_cast<TONE3000Processor&>(*copy);restored.setRateAndBufferSizeDetails(48000,256);restored.prepareToPlay(48000,256);restored.setStateInformation(savedState.getData(),int(savedState.getSize()));require(settled(restored),"restored models loaded");require(std::abs(restored.parameters.getParameter("inputLevel")->getValue()-.61f)<.0001f,"parameter recall");require(restored.getChainState(-1)["chain"].getArray()->size()==p.getChainState(-1)["chain"].getArray()->size(),"chain recall");
 std::unique_ptr<juce::AudioProcessorEditor> editor(restored.createEditorIfNeeded());require(editor&&editor->getWidth()>500,"native editor created");juce::Timer::callAfterDelay(350,[]{juce::MessageManager::getInstance()->stopDispatchLoop();});juce::MessageManager::getInstance()->runDispatchLoop();auto image=editor->createComponentSnapshot(editor->getLocalBounds());require(image.isValid(),"editor rendered");if(argc>2){juce::FileOutputStream output(juce::File(juce::String::fromUTF8(argv[2])));juce::PNGImageFormat png;require(png.writeImageToStream(image,output),"editor screenshot");}editor.reset();
 require(consumeTracksmithTone3000Changes(original.get()),"structural changes notify Tracksmith dirty state");require(!consumeTracksmithTone3000Changes(original.get()),"native change notifications coalesce");ir.deleteFile();p.releaseResources();restored.releaseResources();std::cout<<"PASS: local A2 + IR chain, finite audio, missing-file errors, Tracksmith session/parameter/chain recall, dirty notifications and native editor render.\n";return 0;
}

